public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        String[] relations = input.split(" ");  // 以空格分割多个依赖关系
​
        // 记录依赖key的其它任务应映射，例如 B -> [A] 表示 A 依赖 B
        Map<String, List<String>> depends = new HashMap<>();
        // 记录指定任务所依赖的数量（入度）
        Map<String, Integer> dependCount = new HashMap<>();
​
        for (String relation : relations) {
            String[] tmp = relation.split("->");
            String depend = tmp[0];   // A 依赖 B
            String depended = tmp[1]; // B 被 A 依赖
​
            // 增加 A 的入度
            dependCount.put(depend, dependCount.getOrDefault(depend, 0) + 1);
            // 确保 B 在表中出现（即使它没有依赖任何任务）
            dependCount.putIfAbsent(depended, 0);
​
            // B 被 A 依赖，所以记录 A 到 B 的依赖列表中
            depends.computeIfAbsent(depended, k -> new ArrayList<>()).add(depend);
        }
​
        List<String> res = new ArrayList<>();
        List<String> tmp = new ArrayList<>();
​
        // 找出所有没有依赖的任务（即入度为 0）
        for (String taskId : dependCount.keySet()) {
            if (dependCount.get(taskId) == 0) {
                tmp.add(taskId);
            }
        }
​
        // 拓扑排序过程
        while (!tmp.isEmpty()) {
            List<String> newTmp = new ArrayList<>();
            // 按照字母顺序排序，保证贪心策略
            Collections.sort(tmp);
            for (String id : tmp) {
                res.add(id); // 记录执行顺序
​
                // 处理所有依赖当前任务的任务
                if (depends.containsKey(id)) {
                    for (String depend : depends.get(id)) {
                        dependCount.put(depend, dependCount.get(depend) - 1);
                        // 如果依赖的任务入度变为 0，加入下一轮执行
                        if (dependCount.get(depend) == 0) {
                            newTmp.add(depend);
                        }
                    }
                }
            }
            tmp = newTmp;
        }
​
        // 按顺序输出
        System.out.println(String.join(" ", res));
    }
}
