// 读取标准输入
rl.on('line', function (line) {
    const relations = line.trim().split(" ");  // 空格分隔多个依赖关系
​
    // 记录依赖key的其它任务应映射，例如：B -> [A] 表示 A 依赖 B
    const depends = new Map();
    // 记录每个任务被依赖的次数（入度）
    const dependCount = new Map();
​
    for (const rel of relations) {
        const [depend, depended] = rel.split("->");  // A->B 表示 A 依赖 B
​
        // 更新入度
        dependCount.set(depend, (dependCount.get(depend) || 0) + 1);
        // 确保被依赖任务存在于图中
        if (!dependCount.has(depended)) dependCount.set(depended, 0);
​
        // 添加依赖边
        if (!depends.has(depended)) depends.set(depended, []);
        depends.get(depended).push(depend);
    }
​
    const res = [];
    let tmp = [];
​
    // 找出所有入度为 0 的任务
    for (const [task, count] of dependCount.entries()) {
        if (count === 0) tmp.push(task);
    }
​
    // 拓扑排序过程
    while (tmp.length > 0) {
        tmp.sort();  // 按照字母顺序保证贪心
        const newTmp = [];
​
        for (const id of tmp) {
            res.push(id);
            if (depends.has(id)) {
                for (const dep of depends.get(id)) {
                    dependCount.set(dep, dependCount.get(dep) - 1);
                    if (dependCount.get(dep) === 0) {
                        newTmp.push(dep);
                    }
                }
            }
        }
        tmp = newTmp;
    }
​
    // 输出执行顺序
    console.log(res.join(" "));
    rl.close();
});
