import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strings"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    input := scanner.Text()
    relations := strings.Split(input, " ") // 空格分割多个依赖关系
​
    // 记录依赖key的其它任务应映射，例如：B -> [A] 表示 A 依赖 B
    depends := make(map[string][]string)
    // 记录每个任务被依赖的数量（入度）
    dependCount := make(map[string]int)
​
    for _, rel := range relations {
        parts := strings.Split(rel, "->") // A->B 表示 A 依赖 B
        depend := parts[0]
        depended := parts[1]
​
        dependCount[depend] += 1                 // A 依赖别人，入度 +1
        if _, ok := dependCount[depended]; !ok { // 确保 B 被记录
            dependCount[depended] = 0
        }
        depends[depended] = append(depends[depended], depend)
    }
​
    var res []string
    var tmp []string
​
    // 收集所有入度为 0 的任务（可立即执行）
    for k, v := range dependCount {
        if v == 0 {
            tmp = append(tmp, k)
        }
    }
​
    // 拓扑排序主逻辑
    for len(tmp) > 0 {
        sort.Strings(tmp) // 保证字母顺序，贪心策略
        var newTmp []string
​
        for _, id := range tmp {
            res = append(res, id)
            for _, dep := range depends[id] {
                dependCount[dep]--
                if dependCount[dep] == 0 {
                    newTmp = append(newTmp, dep)
                }
            }
        }
        tmp = newTmp
    }
​
    // 输出最终的任务顺序
    fmt.Println(strings.Join(res, " "))
}
